package com.example.starter.costmap.model;

/**
 * 地图上的矩形区域（单位：格，左上角原点，x 向右、y 向下）。
 *
 * @param x      左上角 x 坐标（含），从 0 开始
 * @param y      左上角 y 坐标（含），从 0 开始
 * @param width  区域宽度（格），至少为 1
 * @param height 区域高度（格），至少为 1
 */
public record Region(int x, int y, int width, int height) {

    /**
     * 判断该区域是否完整落在给定尺寸的地图内。
     */
    public boolean fitsWithin(int mapWidth, int mapHeight) {
        return x >= 0 && y >= 0 && width >= 1 && height >= 1
                && x + width <= mapWidth && y + height <= mapHeight;
    }

    /**
     * 按给定外扩格数扩张区域并裁剪到地图边界，用于膨胀层影响范围计算。
     */
    public Region expand(int cells, int mapWidth, int mapHeight) {
        int nx = Math.max(0, x - cells);
        int ny = Math.max(0, y - cells);
        int nx2 = Math.min(mapWidth, x + width + cells);
        int ny2 = Math.min(mapHeight, y + height + cells);
        return new Region(nx, ny, nx2 - nx, ny2 - ny);
    }

    /**
     * 判断给定格子是否位于区域内。
     */
    public boolean contains(int cx, int cy) {
        return cx >= x && cx < x + width && cy >= y && cy < y + height;
    }
}

package com.example.starter.costmap.model;

/**
 * 一条已应用的动态障碍物记录（不可变）。
 * <p>
 * 合并规则（公开且确定性）：同一格被多个障碍物覆盖时，依次按
 * 优先级大者优先、客户端时间戳大者优先、来源 ID 字典序小者优先 选出唯一胜者，
 * 该格障碍物代价取胜者对应格的值。
 *
 * @param obstacleId  服务端生成的记录标识
 * @param requestId   客户端请求标识（幂等键）
 * @param sourceId    来源标识
 * @param priority    优先级，数值大者优先
 * @param obstacleKey 同一来源内的业务键；同键新更新替换旧记录，可为 null
 * @param region      覆盖区域
 * @param cells       区域行主序代价数组（0-255）
 * @param clientTs    客户端时间戳（纪元毫秒）
 * @param expiresAt   过期时刻（纪元毫秒，UTC），null 表示不过期
 */
public record ObstacleRecord(
        String obstacleId,
        String requestId,
        String sourceId,
        int priority,
        String obstacleKey,
        Region region,
        byte[] cells,
        long clientTs,
        Long expiresAt) {

    /**
     * 返回该障碍物覆盖 (cx, cy) 格时的代价值；调用前须确认区域包含该格。
     */
    public int costAt(int cx, int cy) {
        int lx = cx - region.x();
        int ly = cy - region.y();
        return cells[ly * region.width() + lx] & 0xFF;
    }

    /**
     * 合并决胜比较：返回正数表示 this 优先于 other。
     */
    public int comparePrecedence(ObstacleRecord other) {
        int c = Integer.compare(this.priority, other.priority);
        if (c != 0) {
            return c;
        }
        c = Long.compare(this.clientTs, other.clientTs);
        if (c != 0) {
            return c;
        }
        // 来源 ID 字典序小者优先，因此取反。
        return other.sourceId.compareTo(this.sourceId);
    }
}

