        if (c != 0) {
            return c;
        }
        c = Long.compare(this.clientTs, other.clientTs);
        if (c != 0) {
            return c;
        }
        // 来源 ID 字典序小者优先，因此取反。
        return other.sourceId.compareTo(this.sourceId);
    }
}

