public static int inflationCells(double inflationRadius, double resolution) {
    if (inflationRadius <= 0) return 0;
    return (int) Math.ceil(inflationRadius / resolution);
}

public static Region recomputeRegion(CostmapState state, Region affected) {
    Region clip = new Region(affected.x(), affected.y(), affected.width(), affected.height());
    // clip to map
    int x = Math.max(0, affected.x());
    int y = Math.max(0, affected.y());
    int x2 = Math.min(state.width(), affected.x() + affected.width());
    int y2 = Math.min(state.height(), affected.y() + affected.height());
    Region r = new Region(x, y, x2 - x, y2 - y);
    // 1. base recompute for r
    for each cell in r:
        int cost = staticGrid[idx] & 0xFF;
        ObstacleRecord winner = null;
        for (ObstacleRecord o : state.obstacles()) {
            if (o.region().contains(cx, cy)) {
                if (winner == null || o.comparePrecedence(winner) > 0) winner = o;
            }
        }
        if (winner != null) cost = Math.max(cost, winner.costAt(cx, cy));
        baseGrid[idx] = (byte) cost;
    // 2. inflation for r
    int R = inflationCells(state.inflationRadius(), state.resolution());
    if (R <= 0) { copy base to master for r; return r; }
    for each cell c in r:
        int cost = baseGrid[c] & 0xFF;
        // search neighborhood within R for lethal base cells
        for dy in -R..R, dx in -R..R:
            nx, ny in map bounds
            d2 = dx*dx+dy*dy; if d2 > R*R continue;  // Euclidean
            int n = baseGrid[ny][nx] & 0xFF;
            if (n >= LETHAL) {
                double d = Math.sqrt(d2);
                int ic = inflationCost(d, R);
                cost = Math.max(cost, ic);
            }
        masterGrid[c] = (byte) cost;
    return r;
}
